    }
    match /hd0049/{room} {
      allow read: if resource.data.keys().hasAny(['zz', 's']);
    }
    match /hd0050/{room} {
      allow read: if resource.data.keys().hasOnly(['n']);
    }
    match /hd0051/{room} {
      allow read: if resource.data.m.values().hasAll([1, 'z']);
    }
    match /hd0052/{room} {
      allow read: if resource.data.m == {'x': 1, 'y': 'z'};
    }
    match /hd0053/{room} {
      allow read: if resource.data.m == {'x': 1.0, 'y': 'z'};
    }
    match /hd0054/{room} {
      allow read: if resource.data.m.diff({'x': 1, 'y': 'w'}).affectedKeys() == ['y'].toSet();
    }
    match /hd0055/{room} {
      allow read: if resource.data.m.diff({'x': 1}).addedKeys() == ['y'].toSet();
    }
    match /hd0056/{room} {
      allow read: if resource.data.m.diff({'x': 1, 'q': 2, 'y': 'z'}).removedKeys() == ['q'].toSet();
    }
    match /hd0057/{room} {
      allow read: if resource.data.m.diff({'x': 2, 'y': 'z'}).changedKeys() == ['x'].toSet();
    }
    match /hd0058/{room} {
      allow read: if resource.data.m.diff({'x': 2, 'y': 'z'}).unchangedKeys() == ['y'].toSet();
    }
    match /hd0059/{room} {
      allow read: if resource.data.arr.size() == 3;
    }
  }
}

